import { eq, useLiveQuery } from '@tanstack/vue-db'
import { postsCollection } from '../../data/posts.collection'

/** Query "Featured posts": published posts, newest first, at most `limit`. */
export const useFeaturedPosts = (limit = 6) =>
  useLiveQuery(q => q
    .from({ post: postsCollection })
    .where(({ post }) => eq(post.published, true))
    .orderBy(({ post }) => post.publishedAt, 'desc')
    .limit(limit)
  )
